def run(nodes: dict, edges: dict, start: str, state: dict) -> dict:
    """Walk the graph from `start`, applying nodes, until 'END'. Return state."""
    current = start
    while current != "END":
        state = nodes[current](state)
        current = edges[current]
    return state

nodes = {
    "add": lambda s: {**s, "n": s["n"] + 1},
    "double": lambda s: {**s, "n": s["n"] * 2},
}
edges = {"add": "double", "double": "END"}
print(run(nodes, edges, "add", {"n": 3}))
